"""Reviewed completion of three truncated drafts retained by the selected repair run."""
import json
from pathlib import Path
from expand_lessons import validate
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'tmp/normalized'

def source(locale, lesson):
    p=ROOT/f'tmp/expanded-artifacts/repair-{locale}/{locale}/attempts/{lesson}-attempt-2.txt'
    return json.loads(p.read_text())
def save(d):
    validate(d,d['id'],d['locale'])
    d.update(version='2.0.1-editorial-review',status='GENERATED_REVIEW_REQUIRED',brand='Masaarat',line='academic',courseId='AC-BUS',
        provenance={'method':'retained-draft-with-authored-truncation-repair','reviewAcceptance':'PENDING'},
        media={'provider':'bunny','videoId':None})
    p=OUT/d['locale']/(d['id']+'.json');p.parent.mkdir(exist_ok=True,parents=True)
    p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')

